INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_CIV','The Honeycomb Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_CIV5_HEADING_1','The Council of Hives');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_CIV5_TEXT_1','The Honeycomb Commonwealth is a federation of intelligent honeybees governed through representative hive councils. Separate colonies joined around a common agricultural charter: every worker has a voice, every storehouse has a ledger, and every field has a steward.[NEWLINE][NEWLINE]Its golden cities are built from hexagonal wax structures. Cooperation sustains research, public life and the careful cultivation of flowering resources. Disagreements are settled through elaborate interpretive dances, often followed by extremely detailed committee minutes.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_CIV_PEDIA','The Honeycomb Commonwealth is a federation of intelligent honeybees governed through representative hive councils. Separate colonies joined around a common agricultural charter: every worker has a voice, every storehouse has a ledger, and every field has a steward.[NEWLINE][NEWLINE]Its golden cities are built from hexagonal wax structures. Cooperation sustains research, public life and the careful cultivation of flowering resources. Disagreements are settled through elaborate interpretive dances, often followed by extremely detailed committee minutes.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_DAWN','Honorable Speaker Mellia, Voice of the Thousand Hives, your people await your guidance.[NEWLINE][NEWLINE]Since the dawn of time, your ancestors have traveled from flower to flower, gathering the riches of the earth and transforming them into the golden treasure of the hive.[NEWLINE][NEWLINE]Alone, each worker was small.[NEWLINE][NEWLINE]Together, they accomplished wonders.[NEWLINE][NEWLINE]Now, the scattered colonies have united beneath a common purpose.[NEWLINE][NEWLINE]No longer shall your people live merely to survive.[NEWLINE][NEWLINE]Establish your settlements. Cultivate the fertile earth. Let every worker contribute to the prosperity of the Commonwealth.[NEWLINE][NEWLINE]Will your civilization become the greatest hive the world has ever known?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_DEFEAT_1','The workers... protect the workers... the hive must endure...');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_DUMMY','Commonwealth Collective Labor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_DUMMY_HELP','Automatic Plantation snapshot bonus; cannot be built, bought or sold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_EXCHANGE','Honey Exchange');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_EXCHANGE_HELP','Replaces Market and retains all active Market benefits, specialists and requirements. Adds +1 [ICON_FOOD] Food permanently while present. Each two worked, unpillaged Plantations on your land add +1 [ICON_GOLD] Gold (maximum +2 per city), using the same snapshot as A Thousand Small Hands. Plantations are snapshotted when you end your turn, staging the next owner-turn payout. Assignments changed during a turn do not change its existing bonuses. Interturn changes wait for the following snapshot (CP v151 hook limitation). A new Exchange begins conditional Gold at the next snapshot. Removing it immediately removes that Gold.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_EXCHANGE_PEDIA','The Honey Exchange gathers honey, wax and pollen in vast hexagonal storage halls. Representative councils organize fair distribution, reserve supplies for lean seasons and match workers to the fields that need them. Its prosperity depends on active agricultural work.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_EXCHANGE_STRATEGY','Build Honey Exchanges to support growth and trade. Two qualifying worked Plantations add +1 Gold; four add +2. Unworked, pillaged and foreign Plantations never qualify. The Market class preserves ordinary policy and technology interactions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_FRIENDLY_1','A welcome guest! We have prepared honey and a very short committee agenda.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_GREETING_1','Greetings, traveler! Welcome to the Commonwealth. Please remain calm. The thirty thousand bees surrounding you are merely conducting routine security inspections.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_HOSTILE_1','Your conduct has inspired a most severe interpretive dance. I suggest you take it seriously.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_LEADER','Speaker Mellia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_LEADER_PEDIA','Speaker Mellia, an intelligent golden honeybee with a polished amber ceremonial crown, was elected by the Council of Hives. Polite, organized and diplomatically cautious, she sees collective labor and agricultural security as the foundation of freedom.[NEWLINE][NEWLINE]Mellia listens carefully, speaks precisely and protects the workers above all else. Her sharpest disagreements are expressed through elaborate interpretive dances; foreign envoys are advised to bring a patient interpreter.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_HEADING_1','For the Good of the Hive');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_LIVED','The Age of the Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_NAME','Speaker Mellia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_SUBTITLE','Voice of the Thousand Hives');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_TEXT_1','Speaker Mellia, an intelligent golden honeybee with a polished amber ceremonial crown, was elected by the Council of Hives. Polite, organized and diplomatically cautious, she sees collective labor and agricultural security as the foundation of freedom.[NEWLINE][NEWLINE]Mellia listens carefully, speaks precisely and protects the workers above all else. Her sharpest disagreements are expressed through elaborate interpretive dances; foreign envoys are advised to bring a patient interpreter.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_MELLIA_TITLES_1','Elected Speaker of the Council of Hives');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_NEUTRAL_1','The Council is assembled. Please state your business clearly.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_PEACE_1','Let the workers return to the fields. The Council accepts peace.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_PEACE_OFFER_1','Our gardens need tending. Let us conclude this disagreement before another dance is required.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_PROMOTION','Forager Reconnaissance');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_PROMOTION_HELP','+1 Sight. Lost on upgrade.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SHORT','Honeycomb Commonwealth');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_1','Clover');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_10','Rosemary');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_2','Heather');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_3','Saffron');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_4','Acacia');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_5','Marigold');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_6','Lavender');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_7','Borage');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_8','Linden');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_SPY_9','Verbena');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_STRATEGY','Favor Science or Culture victories. Scout for Plantation resources, improve them with ordinary Workers and actually assign citizens to work them. Reach two worked Plantations per city for Culture and Exchange Gold; four reaches both economic caps. Protect agricultural land. No direct Science, Happiness or combat bonus is granted. Plantations are snapshotted when you end your turn, staging the next owner-turn payout. Assignments changed during a turn do not change its existing bonuses. Interturn changes wait for the following snapshot (CP v151 hook limitation).');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_TRADE_1','The ledgers agree. May this exchange nourish both our peoples.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_TRAIT','A Thousand Small Hands');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_TRAIT_HELP','Each worked, unpillaged Plantation on your own land adds +1 [ICON_PRODUCTION] Production to its city (maximum +4). Cities working at least two also receive +1 [ICON_CULTURE] Culture. These are flat city bonuses. Plantations are snapshotted when you end your turn, staging the next owner-turn payout. Assignments changed during a turn do not change its existing bonuses. Interturn changes wait for the following snapshot (CP v151 hook limitation).');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_UNIT','Forager');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_UNIT_HELP','Replaces Scout. Retains all active Scout properties, requirements, terrain rules and upgrades, with +1 Movement and +1 Sight. The extra Sight is lost on upgrade; no additional combat or Worker abilities.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_UNIT_PEDIA','Foragers travel far beyond the hive to assess nectar, pollen and the safety of agricultural land. Their maps are conveyed through precise dances before the Council of Hives. Their skill lies in reconnaissance, not battle or cultivation.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_UNIT_STRATEGY','Explore flowering valleys and locate Plantation resources. Extra Movement and Sight help survey future settlement sites; a Forager cannot construct improvements. Use normal Scout upgrades when available.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_HCC_WAR_1','You have threatened the hive. The entire hive. Do you understand what that means?');
